
UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "All": {
        "Claimed": " WITH filtered_hiproinst AS ( SELECT hiproinst.proc_def_id_, hiproinst.tenant_id_, hiproinst.state_, hiproinst.end_time_ as \\"Closed Date\\", hiproinst.start_time_ AS \\"Created Date\\", hiproinst.proc_inst_id_, rutask.assignee_, rutask.name_, MAX( CASE WHEN vars.name_ = ''payer'' THEN vars.text_ END ) AS \\"Payer\\", MAX( CASE WHEN vars.name_ = ''payee'' THEN vars.text_ END ) AS \\"Payee\\", MAX( CASE WHEN vars.name_ = ''TransactionAmount'' THEN vars.double_ / 100 END ) AS \\"Amount\\", MAX( CASE WHEN vars.name_ = ''TicketID'' THEN vars.long_ END ) AS \\"Case ID\\", MAX( CASE WHEN vars.name_ = ''Alert'' THEN vars.text_ END ) AS \\"Alert\\", MAX( CASE WHEN vars.name_ = ''basedon'' THEN vars.text_ END ) AS \\"Alert Type\\", MAX( CASE WHEN vars.name_ = ''address'' THEN vars.text_ END ) AS \\"Address\\" FROM camunda.act_hi_procinst hiproinst JOIN camunda.act_ru_task rutask on rutask.proc_inst_id_ = hiproinst.proc_inst_id_ and rutask.assignee_ is not null JOIN camunda.act_hi_varinst vars ON vars.proc_inst_id_ = hiproinst.proc_inst_id_ and vars.name_ in ( ''payer'', ''payee'', ''TransactionAmount'', ''TicketID'', ''Alert'', ''basedon'', ''address'' ) WHERE hiproinst.start_time_ >= :StartDate AND hiproinst.start_time_ <= :EndDate AND hiproinst.state_ = ''ACTIVE'' AND hiproinst.proc_def_key_ IN ( WITH d1 AS ( SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ) SELECT workflowkey FROM ui.workflowmasters WHERE ( workflowid IN ( SELECT mappingid FROM d1 ) OR -1 IN ( SELECT mappingid FROM d1 ) ) AND itenantid = :tenantid AND is_filter_display = true ) AND hiproinst.tenant_id_ = :tenantidstr GROUP BY 1, 2, 3, 4, 5, 6, 7, 8 ORDER BY hiproinst.start_time_ LIMIT 30000 ), ranked_oplog AS ( SELECT proc_inst_id_, time_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY time_ DESC ) AS rn FROM camunda.act_hi_detail WHERE name_ = ''userActivity'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM filtered_hiproinst where state_ = ''ACTIVE'' ) ) SELECT hiproinst.\\"Case ID\\", pdef.name_ AS \\"Case Type\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN hiproinst.name_ ELSE ''Closed'' END AS \\"Stage\\", hiproinst.\\"Alert\\", hiproinst.\\"Payer\\", hiproinst.\\"Amount\\", hiproinst.\\"Payee\\", wu.vcemailid AS \\"Claimed By\\", CASE WHEN hiproinst.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", hiproinst.\\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN hiproinst.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", hiproinst.\\"Closed Date\\", null AS \\"Closed By\\", hiproinst.\\"Alert Type\\", hiproinst.\\"Address\\" FROM filtered_hiproinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ LEFT JOIN ui.webuser wu ON wu.iuserid = CAST(hiproinst.assignee_ AS INTEGER) LEFT JOIN ranked_oplog oplog ON oplog.proc_inst_id_ = hiproinst.proc_inst_id_ AND oplog.rn = 1;",
        "Unclaimed": " WITH filtered_hiproinst AS ( SELECT hiproinst.proc_def_id_, hiproinst.tenant_id_, hiproinst.state_, hiproinst.end_time_ as \\"Closed Date\\", hiproinst.start_time_ AS \\"Created Date\\", hiproinst.proc_inst_id_, rutask.assignee_, rutask.name_, MAX( CASE WHEN vars.name_ = ''payer'' THEN vars.text_ END ) AS \\"Payer\\", MAX( CASE WHEN vars.name_ = ''payee'' THEN vars.text_ END ) AS \\"Payee\\", MAX( CASE WHEN vars.name_ = ''TransactionAmount'' THEN vars.double_ / 100 END ) AS \\"Amount\\", MAX( CASE WHEN vars.name_ = ''TicketID'' THEN vars.long_ END ) AS \\"Case ID\\", MAX( CASE WHEN vars.name_ = ''Alert'' THEN vars.text_ END ) AS \\"Alert\\", MAX( CASE WHEN vars.name_ = ''basedon'' THEN vars.text_ END ) AS \\"Alert Type\\", MAX( CASE WHEN vars.name_ = ''address'' THEN vars.text_ END ) AS \\"Address\\" FROM camunda.act_hi_procinst hiproinst JOIN camunda.act_ru_task rutask on rutask.proc_inst_id_ = hiproinst.proc_inst_id_ and rutask.assignee_ is null JOIN camunda.act_hi_varinst vars ON vars.proc_inst_id_ = hiproinst.proc_inst_id_ and vars.name_ in ( ''payer'', ''payee'', ''TransactionAmount'', ''TicketID'', ''Alert'', ''basedon'', ''address'' ) WHERE hiproinst.start_time_ >= :StartDate AND hiproinst.start_time_ <= :EndDate AND hiproinst.state_ = ''ACTIVE'' AND hiproinst.proc_def_key_ IN ( WITH d1 AS ( SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ) SELECT workflowkey FROM ui.workflowmasters WHERE ( workflowid IN ( SELECT mappingid FROM d1 ) OR -1 IN ( SELECT mappingid FROM d1 ) ) AND itenantid = :tenantid AND is_filter_display = true ) AND hiproinst.tenant_id_ = :tenantidstr GROUP BY 1, 2, 3, 4, 5, 6, 7, 8 ORDER BY hiproinst.start_time_ LIMIT 30000 ) SELECT hiproinst.\\"Case ID\\", pdef.name_ AS \\"Case Type\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN hiproinst.name_ ELSE ''Closed'' END AS \\"Stage\\", hiproinst.\\"Alert\\", hiproinst.\\"Payer\\", hiproinst.\\"Amount\\", hiproinst.\\"P