        "Closed": " WITH filtered_hiproinst AS ( SELECT hiproinst.proc_def_id_, hiproinst.tenant_id_, hiproinst.state_, hiproinst.end_time_ as \\"Closed Date\\", hiproinst.start_time_ AS \\"Created Date\\", hiproinst.proc_inst_id_, MAX( CASE WHEN vars.name_ = ''payer'' THEN vars.text_ END ) AS \\"Payer\\", MAX( CASE WHEN vars.name_ = ''payee'' THEN vars.text_ END ) AS \\"Payee\\", MAX( CASE WHEN vars.name_ = ''TransactionAmount'' THEN vars.double_ / 100 END ) AS \\"Amount\\", MAX( CASE WHEN vars.name_ = ''TicketID'' THEN vars.long_ END ) AS \\"Case ID\\", MAX( CASE WHEN vars.name_ = ''Alert'' THEN vars.text_ END ) AS \\"Alert\\", MAX( CASE WHEN vars.name_ = ''basedon'' THEN vars.text_ END ) AS \\"Alert Type\\", MAX( CASE WHEN vars.name_ = ''address'' THEN vars.text_ END ) AS \\"Address\\" FROM camunda.act_hi_procinst hiproinst JOIN camunda.act_hi_varinst vars ON vars.proc_inst_id_ = hiproinst.proc_inst_id_ and name_ in ( ''payer'', ''payee'', ''TransactionAmount'', ''TicketID'', ''Alert'', ''basedon'', ''address'' ) WHERE hiproinst.start_time_ >= :StartDate AND hiproinst.start_time_ <= :EndDate AND hiproinst.state_ = ''COMPLETED'' AND hiproinst.proc_def_key_ IN ( WITH d1 AS ( SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ) SELECT workflowkey FROM ui.workflowmasters WHERE ( workflowid IN ( SELECT mappingid FROM d1 ) OR -1 IN ( SELECT mappingid FROM d1 ) ) AND itenantid = :tenantid AND is_filter_display = true ) AND hiproinst.tenant_id_ = :tenantidstr GROUP BY 1, 2, 3, 4, 5, 6 ORDER BY hiproinst.start_time_ LIMIT 30000 ), ranked_closedby AS ( SELECT proc_inst_id_, assignee_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC ) AS rn FROM camunda.act_hi_taskinst WHERE proc_inst_id_ IN ( SELECT proc_inst_id_ FROM filtered_hiproinst where state_ = ''COMPLETED'' ) ) SELECT hiproinst.\\"Case ID\\", pdef.name_ AS \\"Case Type\\", ''Closed'' AS \\"Stage\\", hiproinst.\\"Alert\\", hiproinst.\\"Payer\